// Review coverage for #2652: a timed-out website browser shard must not leave
// its transient server holding the shard port, and cleanup must touch only
// processes the shard provably owns.
//
// Every real process here is a short-lived child of this test that listens
// on a port reserved by this test, carries a token generated by this test,
// and is killed in afterEach. Nothing reaches a fixed port or a host service.
import { spawn } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  SHARD_OWNER_ENV,
  SHARD_PORT_ENV,
  SHARD_STATE_ENV,
  cleanupShardServer,
  findOwnedProcesses,
  isPortListening,
  newShardOwnerToken,
  readShardServerState,
  reserveLoopbackPort,
  signalOwnedProcesses,
  snapshotShardBaseline,
} from "../../scripts/lib/website-shard-server.mjs";
import {
  selectWebsiteBrowserShards,
  websiteBrowserShardCleanupStep,
  websiteBrowserShardCommands,
  websiteBrowserShardEnv,
} from "../../scripts/local-ci.mjs";
import { watchRunner } from "../../website/scripts/transient-server.mjs";

const HOST = "127.0.0.1";
const linux = process.platform === "linux" && fs.existsSync("/proc/self/stat");
const euid = process.geteuid();
const tracked = [];
const tempDirs = [];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const waitFor = async (check, ms = 10_000) => {
  const deadline = Date.now() + ms;
  while (Date.now() < deadline) {
    if (await check()) return true;
    await sleep(50);
  }
  return check();
};
const alive = (pid) => {
  try { process.kill(pid, 0); return true; } catch { return false; }
};
const tempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "shard-cleanup-"));
  fs.chmodSync(dir, 0o700);
  tempDirs.push(dir);
  return dir;
};

// A server process listening on `port`; `owner` goes into its environment.
const serverScript = (port) =>
  `require("node:net").createServer().listen(${port}, "${HOST}"); setInterval(() => {}, 1000);`;

function startListener(port, env = {}, { detached = false } = {}) {
  const child = spawn(process.execPath, ["-e", serverScript(port)], {
    env: { PATH: process.env.PATH, ...env }, stdio: "ignore", detached,
  });
  tracked.push(child.pid);
  return child;
}

// Mirrors Playwright: the runner leads one process group and launches the web
// server detached, as the leader of a second group. The runner reports the
// server PID on stdout.
function startFakeShardRunner(port, owner) {
  const runnerScript = `
    const { spawn } = require("node:child_process");
    const server = spawn(process.execPath, ["-e", ${JSON.stringify(serverScript(port))}], {
      detached: true, stdio: "ignore", env: process.env,
    });
    process.stdout.write(String(server.pid) + "\\n");
    setInterval(() => {}, 1000);`;
  const runner = spawn(process.execPath, ["-e", runnerScript], {
    detached: true, stdio: ["ignore", "pipe", "ignore"],
    env: { PATH: process.env.PATH, [SHARD_OWNER_ENV]: owner, [SHARD_PORT_ENV]: String(port) },
  });
  tracked.push(runner.pid);
  const serverPid = new Promise((resolve) => {
    runner.stdout.once("data", (chunk) => {
      const pid = Number(String(chunk).trim());
      tracked.push(pid);
      resolve(pid);
    });
  });
  return { runner, serverPid };
}

// A fake /proc tree so ownership and failure paths run without real signals.
function fakeProc({ processes = {} } = {}) {
  const root = tempDir();
  fs.mkdirSync(path.join(root, "self"));
  fs.writeFileSync(path.join(root, "self", "stat"), "1 (self) S 0 1 1");
  const write = (pid, { owner, uid = euid, startTime = "100", pgid = pid, state = "S" }) => {
    const dir = path.join(root, String(pid));
    fs.mkdirSync(dir, { recursive: true });
    const fields = [state, "1", String(pgid), ...Array(16).fill("0"), startTime];
    fs.writeFileSync(path.join(dir, "stat"), `${pid} (node (srv)) ${fields.join(" ")}`);
    fs.writeFileSync(path.join(dir, "status"), `Name:\tnode\nUid:\t${uid}\t${uid}\t${uid}\t${uid}\n`);
    fs.writeFileSync(path.join(dir, "environ"), ["PATH=/usr/bin", owner ? `${SHARD_OWNER_ENV}=${owner}` : "HOME=/x", ""].join("\0"));
  };
  for (const [pid, spec] of Object.entries(processes)) write(Number(pid), spec);
  return { root, write, remove: (pid) => fs.rmSync(path.join(root, String(pid)), { recursive: true, force: true }) };
}

afterEach(() => {
  for (const pid of tracked.splice(0)) {
    try { process.kill(pid, "SIGKILL"); } catch { /* already gone */ }
  }
  for (const dir of tempDirs.splice(0)) fs.rmSync(dir, { recursive: true, force: true });
});

describe.skipIf(!linux)("shard timeout leaves no server behind", () => {
  it("reproduces the leak after a shard group SIGKILL and cleans up only the owned server", async () => {
    const port = await reserveLoopbackPort();
    const owner = newShardOwnerToken();
    // Host processes with protected environments (agents, sandboxes) predate
    // the shard; local-ci records them the same way before each shard.
    const baseline = snapshotShardBaseline();
    const { runner, serverPid } = startFakeShardRunner(port, owner);
    const pid = await serverPid;
    expect(await waitFor(() => isPortListening(HOST, port))).toBe(true);

    // local-ci's 300-second budget and silence watchdog end a shard this way.
    process.kill(-runner.pid, "SIGKILL");
    expect(await waitFor(() => !alive(runner.pid))).toBe(true);
    // The bug: the web server group survives and keeps the port.
    await sleep(200);
    expect(alive(pid)).toBe(true);
    expect(await isPortListening(HOST, port)).toBe(true);

    const result = await cleanupShardServer({ owner, port, stateFile: path.join(tempDir(), "absent.json"), selfExitMs: 200, pollMs: 25, baseline });
    expect(result).toMatchObject({ ok: true, verification: "procfs", unattributedListener: false, survivors: [], uncertain: [] });
    expect(result.signalled).toEqual([{ pid, signal: "SIGTERM" }]);
    expect(alive(pid)).toBe(false);
    expect(await isPortListening(HOST, port)).toBe(false);
  }, 30_000);

  it("lets the launcher stop its server once the runner is gone", async () => {
    const runner = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], { stdio: "ignore" });
    tracked.push(runner.pid);
    const onGone = vi.fn();
    const stop = watchRunner(runner.pid, { intervalMs: 25, onGone });
    await sleep(100);
    expect(onGone).not.toHaveBeenCalled();
    runner.kill("SIGKILL");
    expect(await waitFor(() => onGone.mock.calls.length === 1)).toBe(true);
    stop();
    expect(() => watchRunner(1, { onGone })).toThrow(/invalid runner PID/);
  }, 15_000);
});

describe.skipIf(!linux)("occupied shard port", () => {
  it("fails cleanup for an unattributed listener on the shard port and never signals it", async () => {
    const baseline = snapshotShardBaseline();
    const port = await reserveLoopbackPort();
    const foreign = startListener(port, {}, { detached: true });
    expect(await waitFor(() => isPortListening(HOST, port))).toBe(true);
    const owner = newShardOwnerToken();
    const kill = vi.fn();

    const result = await cleanupShardServer({ owner, port, stateFile: path.join(tempDir(), "s.json"), selfExitMs: 50, listenerGraceMs: 100, pollMs: 10, kill, baseline });
    expect(result).toMatchObject({ ok: false, unattributedListener: true, signalled: [], uncertain: [] });
    expect(result.reason).toMatch(/unattributed listener .* not signalled/);
    expect(kill).not.toHaveBeenCalled();
    expect(alive(foreign.pid)).toBe(true);
    expect(await isPortListening(HOST, port)).toBe(true);
  }, 15_000);

  it("never signals a process carrying a different shard's token", async () => {
    const baseline = snapshotShardBaseline();
    const port = await reserveLoopbackPort();
    const other = startListener(port, { [SHARD_OWNER_ENV]: newShardOwnerToken() });
    expect(await waitFor(() => isPortListening(HOST, port))).toBe(true);
    const kill = vi.fn();
    const result = await cleanupShardServer({ owner: newShardOwnerToken(), port, stateFile: path.join(tempDir(), "s.json"), selfExitMs: 50, listenerGraceMs: 100, pollMs: 10, kill, baseline });
    expect(result).toMatchObject({ ok: false, unattributedListener: true, signalled: [] });
    expect(kill).not.toHaveBeenCalled();
    expect(alive(other.pid)).toBe(true);
  }, 15_000);

  it("reserves distinct private ports per shard and passes them through the child allowlist", async () => {
    const [a, b] = [await reserveLoopbackPort(), await reserveLoopbackPort()];
    for (const port of [a, b]) expect(Number.isInteger(port) && port > 0 && port <= 65535).toBe(true);

    const shards = selectWebsiteBrowserShards([{ key: "a" }, { key: "b" }], 2);
    const commands = websiteBrowserShardCommands("/w", shards, { browser: "/b", outputRoot: "/o", reportRoot: "/r" });
    const owners = commands.map(([, , , opts]) => opts.server.owner);
    expect(new Set(owners).size).toBe(2);
    commands.forEach(([, , , opts], i) => {
      expect(opts.server.stateFile).toBe(`/o/shard-${i + 1}-server.json`);
      expect(opts.env[SHARD_STATE_ENV]).toBe(opts.server.stateFile);
      expect(opts.env[SHARD_OWNER_ENV]).toBe(opts.server.owner);
      expect(opts.env).not.toHaveProperty(SHARD_PORT_ENV);
    });
    const env = websiteBrowserShardEnv(commands[0][3], a);
    expect(env[SHARD_PORT_ENV]).toBe(String(a));
    expect(env[SHARD_OWNER_ENV]).toBe(owners[0]);
    for (const bad of [0, 80, 70000, 1.5, "3100"]) {
      expect(() => websiteBrowserShardEnv(commands[0][3], bad)).toThrow(/invalid website browser shard port/);
    }
  });
});

describe("ownership checks before any signal", () => {
  const owner = "a".repeat(32);

  it("matches only same-uid processes carrying the shard token", () => {
    const proc = fakeProc({
      processes: {
        101: { owner },
        102: { owner: "b".repeat(32) },
        103: {},
        104: { owner, uid: euid + 1 },
        105: { owner, state: "Z" },
      },
    });
    expect(findOwnedProcesses(owner, { procRoot: proc.root, euid, selfPid: 0 }).map((p) => p.pid)).toEqual([101]);
  });

  it("skips a PID that was reused after the scan", () => {
    const proc = fakeProc({ processes: { 201: { owner, startTime: "500" }, 202: { owner, startTime: "600", pgid: 1 } } });
    const seen = findOwnedProcesses(owner, { procRoot: proc.root, euid, selfPid: 0 });
    // 201 exits and its PID goes to an unrelated program; 202 stays.
    proc.remove(201);
    proc.write(201, { startTime: "900" });
    const kill = vi.fn();
    const signalled = signalOwnedProcesses(seen, "SIGTERM", { owner, procRoot: proc.root, euid, kill });
    expect(kill.mock.calls).toEqual([[202, "SIGTERM"]]);
    expect(signalled).toEqual([{ pid: 202, signal: "SIGTERM" }]);

    // Same token, different start time: still a different process.
    proc.remove(202);
    proc.write(202, { owner, startTime: "601", pgid: 1 });
    kill.mockClear();
    signalOwnedProcesses(seen, "SIGKILL", { owner, procRoot: proc.root, euid, kill });
    expect(kill).not.toHaveBeenCalled();
  });

  it("signals a verified group leader by PID, never its group", () => {
    const proc = fakeProc({ processes: { 301: { owner, pgid: 301 } } });
    const kill = vi.fn();
    const seen = findOwnedProcesses(owner, { procRoot: proc.root, euid, selfPid: 0 });
    signalOwnedProcesses(seen, "SIGTERM", { owner, procRoot: proc.root, euid, kill });
    expect(kill.mock.calls).toEqual([[301, "SIGTERM"]]);
  });

  it("accepts only a private regular state file naming the same owner and port", () => {
    const dir = tempDir();
    const file = path.join(dir, "state.json");
    const write = (state, mode = 0o600) => { fs.writeFileSync(file, JSON.stringify(state), { mode }); fs.chmodSync(file, mode); };
    expect(readShardServerState(file, { owner, port: 4000, euid }).reason).toBe("absent");
    write({ owner, port: 4000, pid: 5 });
    expect(readShardServerState(file, { owner, port: 4000, euid }).state).toMatchObject({ pid: 5 });
    expect(readShardServerState(file, { owner: "c".repeat(32), port: 4000, euid }).reason).toBe("owner mismatch");
    expect(readShardServerState(file, { owner, port: 4001, euid }).reason).toBe("port mismatch");
    expect(readShardServerState(file, { owner, port: 4000, euid: euid + 1 }).reason).toBe("owned by another user");
    write({ owner, port: 4000 }, 0o644);
    expect(readShardServerState(file, { owner, port: 4000, euid }).reason).toBe("not private");
    const link = path.join(dir, "link.json");
    fs.symlinkSync(file, link);
    expect(readShardServerState(link, { owner, port: 4000, euid }).reason).toBe("not a regular file");
  });

  it("refuses malformed tokens and ports instead of scanning broadly", async () => {
    await expect(cleanupShardServer({ owner: "", port: 4000 })).rejects.toThrow(/owner token/);
    await expect(cleanupShardServer({ owner: "A".repeat(32), port: 4000 })).rejects.toThrow(/owner token/);
    await expect(cleanupShardServer({ owner, port: 0 })).rejects.toThrow(/port/);
  });
});

describe("cleanup failure fails closed", () => {
  const owner = "d".repeat(32);
  const probe = async () => false;

  it("reports owned survivors after SIGTERM and SIGKILL", async () => {
    const proc = fakeProc({ processes: { 401: { owner, pgid: 401 } } });
    const kill = vi.fn();
    const result = await cleanupShardServer({
      owner, port: 4000, stateFile: path.join(proc.root, "s.json"), procRoot: proc.root, euid, kill, probe,
      selfExitMs: 20, termMs: 20, killMs: 20, pollMs: 5,
    });
    expect(result.ok).toBe(false);
    expect(result.survivors).toEqual([401]);
    expect(result.reason).toMatch(/survived cleanup: 401/);
    expect(kill.mock.calls).toEqual([[401, "SIGTERM"], [401, "SIGKILL"]]);
  });

  it("fails when the kernel refuses the signal", async () => {
    const proc = fakeProc({ processes: { 402: { owner } } });
    const kill = vi.fn(() => { throw Object.assign(new Error("denied"), { code: "EPERM" }); });
    const result = await cleanupShardServer({
      owner, port: 4000, stateFile: path.join(proc.root, "s.json"), procRoot: proc.root, euid, kill, probe,
      selfExitMs: 10, pollMs: 5,
    });
    expect(result).toMatchObject({ ok: false, survivors: [402] });
    expect(result.reason).toMatch(/signal failed: EPERM/);
  });

  it("treats an already exited process as cleaned up", async () => {
    const proc = fakeProc({ processes: { 403: { owner } } });
    const kill = vi.fn(() => {
      proc.remove(403);
      throw Object.assign(new Error("gone"), { code: "ESRCH" });
    });
    const result = await cleanupShardServer({
      owner, port: 4000, stateFile: path.join(proc.root, "s.json"), procRoot: proc.root, euid, kill, probe,
      selfExitMs: 10, termMs: 50, pollMs: 5,
    });
    expect(result.ok).toBe(true);
  });

  it("fails closed without /proc when the port stays held, and signals nothing", async () => {
    const kill = vi.fn();
    const result = await cleanupShardServer({
      owner, port: 4000, procRoot: path.join(tempDir(), "missing"), kill, probe: async () => true, selfExitMs: 30, pollMs: 5,
    });
    expect(result).toMatchObject({ ok: false, verification: "port-only" });
    expect(result.reason).toMatch(/cannot be verified/);
    expect(kill).not.toHaveBeenCalled();
  });

  it("removes this shard's state file after a verified cleanup", async () => {
    const proc = fakeProc();
    const stateFile = path.join(proc.root, "s.json");
    fs.writeFileSync(stateFile, JSON.stringify({ owner, port: 4000 }), { mode: 0o600 });
    const result = await cleanupShardServer({ owner, port: 4000, stateFile, procRoot: proc.root, euid, probe, selfExitMs: 10 });
    expect(result.ok).toBe(true);
    expect(fs.existsSync(stateFile)).toBe(false);
  });

  it("turns a failed or impossible cleanup into a failed local-ci check", async () => {
    const opts = { server: { owner, stateFile: "/o/shard-1-server.json" } };
    const failed = await websiteBrowserShardCleanupStep("website-browser-shard-1", opts, 4000,
      async () => ({ ok: false, reason: "owned shard server processes survived cleanup: 9", survivors: [9], signalled: [], verification: "procfs" }));
    expect(failed).toMatchObject({ id: "website-browser-shard-1-server-cleanup", kind: "check", status: "failed", survivors: [9] });

    const thrown = await websiteBrowserShardCleanupStep("website-browser-shard-1", opts, 4000,
      async () => { throw new Error("boom"); });
    expect(thrown).toMatchObject({ status: "failed", reason: "shard server cleanup could not be established: boom" });

    const listener = await websiteBrowserShardCleanupStep("website-browser-shard-1", opts, 4000,
      async () => ({ ok: false, reason: "an unattributed listener still holds shard port 4000; it was not signalled",
        unattributedListener: true, signalled: [], survivors: [], uncertain: [], verification: "procfs" }));
    expect(listener).toMatchObject({ status: "failed", unattributedListener: true, signalled: [] });

    const baseline = ["77:123"];
    const seen = vi.fn(async () => ({ ok: true, signalled: [], survivors: [], uncertain: [], unattributedListener: false, verification: "procfs" }));
    const passed = await websiteBrowserShardCleanupStep("website-browser-shard-1", opts, 4000, seen, { baseline });
    expect(passed).toMatchObject({ status: "passed", reason: "shard server stopped", unattributedListener: false, uncertain: [] });
    expect(seen).toHaveBeenCalledWith(expect.objectContaining({ owner, port: 4000, baseline }));
  });
});
